//
//  LumeTheme.swift
//  Lume
//
//  The brand palette, from the redesign's foundations. The neutrals are colour
//  sets in `Assets.xcassets`, generated by Xcode as `Color.lume…`; the brand
//  roles — accent, pink deep, on-accent, selection, violet — come from the
//  colour theme the viewer picked (`LumeColorTheme`), defined below. The
//  values given here are Lume pink's:
//
//  - `lumeAccent` — Lume pink: progress, selection, the mark. #FF88D7 on dark
//    (9.2:1 on Night) and on tvOS; #B8237F ("pink deep") in light appearance,
//    5.9:1 on white. White text on the dark pink is only 2.2:1, so anything
//    drawn *on* an accent fill uses `lumeOnAccent` (white on deep, Ink on pink,
//    8.7:1).
//  - `lumePinkDeep` — #B8237F everywhere: fills that carry a white glyph.
//  - `lumeNight` #0A0810 — the app ground behind artwork.
//  - `lumeInk` #14101F — the brand ground: launch, splash, player wait.
//  - `lumeViolet` #7000B4 — depth behind brand moments (the ambient glow);
//    never text.
//  - `lumeLiveRed` #D7263D — the LIVE badge fill.
//  - `lumeDestructive` — destructive text: #FF453A on dark and tvOS,
//    #D7263D in light. On a white tvOS focus surface use `lumeLiveRed` instead.
//  - `lumeTextSecondary` / `lumeTextTertiary` — secondary and tertiary text:
//    #B9B5C4 / #8E8A99 on dark and tvOS, #55506A / #6F6A80 in light.
//  - `lumeSelection` — selected chips, tabs and rows: Lume pink at 18% on dark,
//    pink deep at 10% in light.
//  - `lumeGround` — the plain-screen ground: Night on dark, Day #F7F5FA in light.
//
//  Focus stays white, as tvOS draws it. Interface text is the system font;
//  Unbounded is the wordmark only (`LumeWordmark`).
//
//  On iPhone, iPad and Mac the accent is also the scene's tint, as the light
//  and dark foundations specify: selected tabs, primary buttons, links and
//  toggles, with destructive roles still the system red. It stays out of the
//  app's `AccentColor`, and tvOS sets no tint: there it would recolour the tab
//  bar's selection and the focus treatment, which stay as tvOS draws them.
//  The sets' `tv` entries hold the dark value under both appearances: Lume's
//  tvOS screens are always dark, even on a TV set to a light appearance.

import SwiftUI

/// The brand roles, from the theme in use. Reading one in a view's body
/// observes the theme, so the view redraws when it changes; a colour stored
/// outside a body (a `static let`) would keep the theme it was made in.
extension Color {
    static var lumeAccent: Color {
        LumeThemeStore.shared.palette.accent
    }

    /// The deep shade, in both appearances. Named for the pink it began as.
    static var lumePinkDeep: Color {
        LumeThemeStore.shared.palette.deep
    }

    static var lumeOnAccent: Color {
        LumeThemeStore.shared.palette.onAccent
    }

    static var lumeSelection: Color {
        LumeThemeStore.shared.palette.selection
    }

    /// The ambient depth hue. Named for the violet it began as.
    static var lumeViolet: Color {
        LumeThemeStore.shared.palette.glow
    }

    /// The accent's bright shade in any appearance.
    static var lumeAccentBright: Color {
        LumeThemeStore.shared.palette.bright
    }
}

/// The shorthand the asset catalogue generated for the roles that were
/// colour sets: `.foregroundStyle(.lumeAccent)`.
extension ShapeStyle where Self == Color {
    static var lumeAccent: Color {
        Color.lumeAccent
    }

    static var lumePinkDeep: Color {
        Color.lumePinkDeep
    }

    static var lumeOnAccent: Color {
        Color.lumeOnAccent
    }

    static var lumeSelection: Color {
        Color.lumeSelection
    }

    static var lumeViolet: Color {
        Color.lumeViolet
    }
}

extension Color {
    /// Brand status/progress on a resting TV row or its native white focus fill.
    /// Accent-filled controls instead use `lumeOnAccent` for their foreground.
    static func lumeFocusAwareAccent(isFocused: Bool) -> Color {
        isFocused ? .lumePinkDeep : .lumeAccent
    }

    /// Red text on the resting Settings surface or its white tvOS focus lift.
    static func lumeDestructiveText(isFocused: Bool) -> Color {
        isFocused ? .lumeLiveRed : .lumeDestructive
    }

    /// A layout row's Top Shelf button while the row is on the tvOS Top Shelf.
    static let topShelfGold = Color(red: 0.96, green: 0.77, blue: 0.29)
}
